def find_author_by_key(author: dict[str, Any]) -> "Author | None":
    """Resolve an imported Open Library author key, following redirects."""
    key = author.get('key')
    if not isinstance(key, str) or not key:
        return None
    if not key.startswith('/'):
        key = f"/authors/{key}"

    existing = web.ctx.site.get(key)
    seen = set()
    while existing and existing.type.key == '/type/redirect':
        if existing.key in seen:
            return None
        seen.add(existing.key)
        location = existing.get('location')
        if isinstance(location, dict):
            location = location.get('key')
        if not location:
            return None
        existing = web.ctx.site.get(location)

    if existing and existing.type.key == '/type/author':
        return existing
    return None


def find_author_by_remote_ids(author: dict[str, Any]) -> "Author | None":
    """Find the strongest deterministic match from an import's remote IDs."""
    remote_ids = author.get('remote_ids') or {}
    if not remote_ids:
        return None

    matches = {}
    for identifier_type, identifier in sorted(remote_ids.items()):
        if not identifier:
            continue
        query = {
            'type': '/type/author',
            f'remote_ids.{identifier_type}': identifier,
        }
        for key in web.ctx.site.things(query):
            matches[key] = web.ctx.site.get(key)

    matches = [a for a in matches.values() if a and a.type.key == '/type/author']
    if not matches:
        return None

    def match_rank(existing: "Author") -> tuple[int, int, int | str, str]:
        existing_ids = existing.get('remote_ids', {}) or {}
        matching_count = sum(
            1
            for identifier_type, identifier in remote_ids.items()
            if identifier and existing_ids.get(identifier_type) == identifier
        )
        return (-matching_count, *author_key_sort_key(existing))

    return min(matches, key=match_rank)


